+   /**
+    * Safely write a zip entry into a target directory. This method ensures
+    * that the resolved canonical path of the destination file is contained
+    * within the supplied directory to prevent path traversal (zip-slip).
+    */
+   public static void writeEntryToDirectory(File directory, ZipEntry entry, InputStream input) throws IOException
+   {
+      if (directory == null)
+      {
+         throw new IOException("Target directory is null");
+      }
+
+      String entryName = entry.getName();
+
+      // Normalize entry name to use platform separators for Path resolution
+      Path targetPath = Paths.get(directory.getPath()).resolve(entryName).normalize();
+
+      // Resolve canonical paths to handle symlinks and .. segments
+      File targetFile = targetPath.toFile();
+
+      String canonicalBase = directory.getCanonicalPath();
+      String canonicalTarget = targetFile.getCanonicalPath();
+
+      // Ensure canonicalTarget is inside canonicalBase. Append separator to avoid prefix attacks:
+      // e.g. /tmp/dir and /tmp/dir_evil
+      if (!canonicalTarget.equals(canonicalBase) && !canonicalTarget.startsWith(canonicalBase + File.separator))
+      {
+         throw new IOException("Entry is outside of the target dir: " + entryName);
+      }
+
+      if (entry.isDirectory())
+      {
+         if (!targetFile.exists() && !targetFile.mkdirs())
+         {
+            throw new IOException("Unable to create directory: " + targetFile);
+         }
+         return;
+      }
+
+      File parent = targetFile.getParentFile();
+      if ((parent != null) && !parent.exists())
+      {
+         if (!parent.mkdirs())
+         {
+            throw new IOException("Unable to create parent directories: " + parent);
+         }
+      }
+
+      try (BufferedOutputStream out = new BufferedOutputStream(new FileOutputStream(targetFile)))
+      {
+         byte[] buffer = new byte[8192];
+         int len;
+         while ((len = input.read(buffer)) != -1)
+         {
+            out.write(buffer, 0, len);
+         }
+      }
