+import React from "react";
+
+type Props = {
+  // Untrusted HTML string intended for display inside an embed.
+  srcDoc: string;
+  // Optional URL source for the iframe. When provided, it will be used
+  // instead of srcDoc.
+  src?: string;
+  // Whether this embed requires same-origin iframe access. Only when true
+  // the allow-same-origin sandbox flag will be set.
+  allowSameOrigin?: boolean;
+};
+
+// Minimal HTML-escaping for embedding untrusted content inside an iframe.
+// We intentionally encode all characters that could form HTML to ensure the
+// provided content is treated as text, not markup.
+function escapeHtml(s: string): string {
+  return s
+    .replace(/&/g, "&amp;")
+    .replace(/</g, "&lt;")
+    .replace(/>/g, "&gt;")
+    .replace(/"/g, "&quot;")
+    .replace(/'/g, "&#39;");
+}
+
+export default function Embed({ srcDoc, src, allowSameOrigin }: Props) {
+  // Build sandbox flags following principle of least privilege.
+  const sandboxFlags = ["allow-scripts"];
+  if (allowSameOrigin) {
+    sandboxFlags.push("allow-same-origin");
+  }
+
+  // Prefer a safe src URL when provided.
+  if (src) {
+    return <iframe src={src} sandbox={sandboxFlags.join(" ")} />;
+  }
+
+  // When rendering srcDoc, do not inject the raw HTML. Instead encode the
+  // user-provided string so it is rendered as text content inside the
+  // iframe. This prevents injection of tags or attributes.
+  const safeDoc = `<!doctype html><html><head><meta charset="utf-8"></head><body><div id="excalidraw-embed">${escapeHtml(
+    srcDoc || ""
+  )}</div></body></html>`;
+
+  return <iframe srcDoc={safeDoc} sandbox={sandboxFlags.join(" ")} />;
+}
