+  if (typeof populate === 'string') {
+    // comma separated list or single relation
+    return populate.split(',').reduce((acc, part) => {
+      const p = part.trim();
+      if (!p) return acc;
+      acc[p] = true;
+      return acc;
+    }, {});
+  }
+
+  if (Array.isArray(populate)) {
+    return populate.reduce((acc, item) => {
+      if (typeof item === 'string') {
+        acc[item] = true;
+      } else if (isObject(item)) {
+        Object.keys(item).forEach(k => {
+          acc[k] = item[k];
+        });
+      }
+      return acc;
+    }, {});
+  }
+
+  if (isObject(populate)) {
+    // Already an object; clone to avoid mutating caller
+    return _.cloneDeep(populate);
+  }
+
+  return {};
