+const crypto = require('crypto');
+
+// Secure keystore helpers.
+// Use PBKDF2 + AES-256-GCM to protect private keys stored for username/password auth.
+// This replaces earlier behaviour that either stored key material in plaintext or
+// used unauthenticated encryption, allowing server operators to obtain users' keys.
+
+const DEFAULT_PBKDF2_ITERS = 100000;
+
+function deriveKey(password, salt, iterations) {
+  return crypto.pbkdf2Sync(password, salt, iterations, 32, 'sha256');
+}
+
+function encryptWithPassword(plaintext, password, opts = {}) {
+  const salt = opts.salt || crypto.randomBytes(16);
+  const iterations = opts.iterations || DEFAULT_PBKDF2_ITERS;
+  const key = deriveKey(password, salt, iterations);
+  const iv = opts.iv || crypto.randomBytes(12); // 96-bit recommended for GCM
+  const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
+  const ciphertext = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
+  const tag = cipher.getAuthTag();
+  return {
+    salt: salt.toString('base64'),
+    iv: iv.toString('base64'),
+    tag: tag.toString('base64'),
+    iterations,
+    ciphertext: ciphertext.toString('base64')
+  };
+}
+
+function decryptWithPassword(payload, password) {
+  const salt = Buffer.from(payload.salt, 'base64');
+  const iv = Buffer.from(payload.iv, 'base64');
+  const tag = Buffer.from(payload.tag, 'base64');
+  const ciphertext = Buffer.from(payload.ciphertext, 'base64');
+  const iterations = payload.iterations || DEFAULT_PBKDF2_ITERS;
+  const key = deriveKey(password, salt, iterations);
+  const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
+  decipher.setAuthTag(tag);
+  const decrypted = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
+  return decrypted.toString('utf8');
+}
+
+module.exports = {
+  // Persist a private key blob for an account. `password` is required for
+  // username/password accounts to allow the server to store only an authenticated
+  // ciphertext (so server operators cannot trivially obtain plaintext).
+  async storeEncryptedPrivateKey(db, accountId, privateKeyPem, password) {
+    if (!password) {
+      // For account types that do not provide a password (e.g. oauth, external keystores),
+      // callers should handle secure storage. Do not accept empty passwords here.
+      throw new Error('Password required to store encrypted private key');
+    }
+    const payload = encryptWithPassword(privateKeyPem, password);
+    await db.accounts.update({ id: accountId }, { $set: { encryptedPrivateKey: payload } });
+  },
+
+  // Retrieve and decrypt a private key that was stored with storeEncryptedPrivateKey.
+  // Returns plaintext PEM on success or null if record not found.
+  async retrieveEncryptedPrivateKey(db, accountId, password) {
+    const rec = await db.accounts.findOne({ id: accountId }, { encryptedPrivateKey: 1 });
+    if (!rec || !rec.encryptedPrivateKey) return null;
+    return decryptWithPassword(rec.encryptedPrivateKey, password);
+  },
+
+  // Export helpers for testing and migration
+  _encryptWithPassword: encryptWithPassword,
+  _decryptWithPassword: decryptWithPassword
+};
