+const {spawn} = require('child_process');
+const path = require('path');
+
+/**
+ * openStackFrameMiddleware
+ *
+ * Security:
+ * - Rejects any request that attempts to pass an arbitrary command string.
+ * - Accepts only a file path (and optional numeric line/column) and opens that
+ *   file with the platform-native opener without invoking a shell.
+ *
+ * This prevents OS command injection by avoiding shell invocation and by
+ * validating inputs at the trust boundary (network -> local execution).
+ */
+module.exports = function openStackFrameMiddleware() {
+  return (req, res) => {
+    const body = req.body || {};
+    const {file, line, column, command} = body;
+
+    if (!file || typeof file !== 'string') {
+      res.status(400).send('Missing or invalid "file"');
+      return;
+    }
+
+    // Reject any attempt to provide a custom command. Executing arbitrary
+    // commands from network input is unsafe.
+    if (command) {
+      res.status(400).send('Custom commands are not allowed');
+      return;
+    }
+
+    // Basic validation for line/column if provided.
+    if (line != null && !Number.isInteger(line)) {
+      res.status(400).send('"line" must be an integer');
+      return;
+    }
+    if (column != null && !Number.isInteger(column)) {
+      res.status(400).send('"column" must be an integer');
+      return;
+    }
+
+    // Resolve the path to an absolute path to avoid surprises with relative paths.
+    // We do not attempt to restrict paths further here (editors typically open
+    // arbitrary files), but we do ensure the value is a normalized string.
+    let resolved;
+    try {
+      resolved = path.resolve(file);
+    } catch (err) {
+      res.status(400).send('Invalid file path');
+      return;
+    }
+
+    // Platform-specific opener that can be invoked without a shell.
+    // We pass the filename as a single argument to avoid any shell parsing.
+    let opener;
+    let openerArgs = [resolved];
+    switch (process.platform) {
+      case 'darwin':
+        opener = 'open';
+        // macOS 'open' supports +LINE:COL via editors' custom URL schemes; keep
+        // it simple and only pass the path.
+        break;
+      case 'win32':
+        // Avoid using 'start' (cmd builtin). 'explorer' can be used to open files.
+        opener = 'explorer';
+        break;
+      default:
+        opener = 'xdg-open';
+    }
+
+    // Spawn the opener directly without a shell to prevent command injection.
+    const child = spawn(opener, openerArgs, {stdio: 'ignore', detached: true});
+    // Detach so the child can continue after the server process exits.
+    child.unref();
+
+    // child.spawn errors are reported via 'error' event.
+    let handled = false;
+    child.on('error', (err) => {
+      if (handled) return;
+      handled = true;
+      res.status(500).send(String(err));
+    });
+
+    // If the process was spawned successfully we immediately return success.
+    // The actual opener may fail asynchronously on the client system; that's
+    // outside the scope of the dev server.
+    if (!handled) {
+      res.status(200).send('OK');
+    }
+  };
